import { names } from '../data';

function Tables() {
    return (
        <section>
            <table>
                <thead>
                    <tr>
                        <th>Name</th>
                    </tr>
                    <tr>
                        {names.map(name => 
                        <th>
                            name
                        </th>)}
                        <th>Year</th>
                        <th>Investment Value</th>
                        <th>Interest (Year)</th>
                        <th>Total Interest</th>
                        <th>Invested Capital</th>
                    </tr>
                </thead>
            </table>
        </section>
    );
}

export default Tables;
